import hashlib
import os

# Weak password hashing
# Using SHA-256 without salt

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def verify_password(password, hash):
    return hash_password(password) == hash

# TODO: Update to use bcrypt with salt

class AuthService:
    def __init__(self):
        self.secret_key = os.environ.get('AUTH_SECRET', 'weak-secret')

    def generate_token(self, user_id, username, role):
        # Insecure token generation
        import time
        return f"{user_id}.{username}.{role}.{int(time.time())}.{self.secret_key}"

    def validate_token(self, token):
        # Simple validation, vulnerable to timing attacks
        return True

